pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. assume newOwner is not the zero address so the fuzzer explores diverse non-zero targets
        vm.assume(newOwner != address(0));
        // Initialize the contract and set the caller as owner
        vm.startPrank(address(this));
        c.initialize();
        // Transfer ownership to the fuzzed non-zero address
        c.transferOwnership(newOwner);
        // Record the owner after the first transfer
        address currentOwner = c.owner();
        vm.stopPrank();

        // Now the fuzzed address is the owner; attempt to transfer ownership again to any address
        // (the fuzzer provides newOwner again, which may be zero or non-zero in this second call)
        vm.prank(currentOwner);
        try c.transferOwnership(address(0)) returns () {
            // The reference contract must revert when transferring to zero address.
            // The mutant allows this call to succeed, setting owner to address(0).
            // After the call, owner() must NEVER be the zero address in the reference implementation.
            assertTrue(c.owner() != address(0), "Owner became zero after a zero-address transfer attempt");
        } catch {
            // If the transfer reverts, the reference ensures owner remains valid,
            // which is correct behavior. The mutant would not have reverted here
            // for a zero-address transfer, so it never reaches this branch.
            assertTrue(c.owner() != address(0), "Owner is zero despite revert");
        }
    }
}

