pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Keep the allowed input wide; the only assumption is that the original caller
        // is the owner (required by onlyOwner). We set the owner with a pranked deploy.
        address originalOwner = address(0x1234);
        vm.prank(originalOwner);
        c.transferOwnership(originalOwner);

        // Now prank as the owner and attempt the transfer
        vm.prank(originalOwner);
        bool ok = true;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // For the reference implementation, a call with the zero address MUST revert
        // (so ok == false). For the mutant, the zero-address call succeeds (ok == true),
        // and after the call the owner would be address(0).
        // The universal rule: if the call succeeds, the new owner must not be address(0).
        // This holds for the reference (since it can never succeed with zero address),
        // and fails for the mutant when newOwner == address(0).
        if (ok) {
            assertTrue(c.owner() != address(0));
        } else {
            // The call reverted, so the owner must remain unchanged (not zero)
            assertTrue(c.owner() != address(0));
        }
    }
}

