pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newImpl) public {
        // Ensure the deployer (this contract) is the owner after initialization
        c.initialize();
        address owner = c.owner();
        // The fuzzed address must not be the zero address to be an admissible input.
        // The reference requires non-zero address; the mutant removes this check.
        // We allow the fuzzer to supply any address, including address(0).
        // Even with address(0) the mutant will set roundImplementation to address(0),
        // but the reference will revert (so roundImplementation stays at the old value,
        // which is address(0) because it was never set) — wait, roundImplementation initially is 0.
        // If both start at 0, setting to 0 in mutant and reverting (staying 0) in reference
        // would not differ. So we first set a non-zero roundImplementation to create a
        // distinguishable state. We need to bypass the zero-address check in the reference
        // to set a baseline. The only way is to use a non-zero address first.
        // So we first set roundImplementation to a non-zero address (the address of a
        // new contract) via the owner to establish a baseline state where roundImplementation
        // is non-zero. This call will succeed in both versions.
        // Deploy a contract to use as the initial non-zero implementation.
        vm.startPrank(owner);
        c.updateRoundImplementation(payable(address(this))); // set to non-zero (self)
        // Now roundImplementation = address(this) in both.
        // Record the value before the fuzzed update.
        address oldImpl = c.roundImplementation();
        // Now call updateRoundImplementation with the fuzzed address.
        // We allow the fuzzer to supply any address, including zero.
        try c.updateRoundImplementation(payable(newImpl)) {} catch {}
        // After the call, the reference's roundImplementation should equal newImpl
        // if newImpl != address(0), or remain oldImpl if newImpl == address(0) (due to revert).
        // The mutant always sets roundImplementation to newImpl regardless.
        // The property: if the call did not revert, then the new roundImplementation must be newImpl.
        // But we cannot use try/catch boolean because the property must hold for all inputs.
        // Instead, we assert a universal invariant: roundImplementation is never zero
        // after a successful update? No, because the reference can have zero if never set.
        // Let's reason: after the first non-zero set, roundImplementation is non-zero.
        // In the reference, it stays non-zero because any attempt to set to zero reverts.
        // In the mutant, it becomes zero. So the invariant "roundImplementation != address(0)"
        // holds in the reference but is broken in the mutant after a call with address(0).
        // This is a public state variable, so we can assert it directly.
        // However, the fuzzer may supply a non-zero address, in which case both set it correctly.
        // The assertion must hold for ALL inputs. So asserting roundImplementation != address(0)
        // would fail in the reference if the initial set never happened? But we always set it first.
        vm.stopPrank();
        assertTrue(c.roundImplementation() != address(0));
    }
}

